const api=async<T,>(path:string, options:RequestInit={}, token=''):Promise<T>=>{const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{ }),...(options.headers||{})}});if(!res.ok){const msg=(await res.json().catch(()=>({message:'请求失败'}))).message||`请求失败 (${res.status})`;if(res.status===401&&token){localStorage.removeItem('tb-token');localStorage.removeItem('tb-user');window.dispatchEvent(new Event('tb-auth-expired'));}throw new Error(msg);}const text=await res.text();return (text?JSON.parse(text):undefined) as T};
const time=(v:string)=>new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v));
marked.use({breaks:true,gfm:true,renderer:{code({text,lang}:Tokens.Code){let o:string;if(lang&&hljs.getLanguage(lang))o=hljs.highlight(text,{language:lang}).value;else o=hljs.highlightAuto(text).value;return `<pre><code class="hljs${lang?` language-${lang}`:''}">${o}</code></pre>`}}});
const renderMd=(text:string):string=>DOMPurify.sanitize(marked.parse(text) as string);

