 useEffect(()=>{loadForums();loadPopularTags()},[]); useEffect(()=>{loadPosts()},[active?.slug,order,seed,page,globalMode,activeTag]); useEffect(()=>{if(active)api<UserProfile[]>(`/api/forums/${active.slug}/moderators`).then(r=>setMods(r.map(m=>m.username))).catch(e=>{console.warn('API:',e);setMods([])})},[active?.slug]); useEffect(()=>{if(token)api<{verified:boolean;role?:string}>('/api/auth/me',{},token).then(d=>{setVerified(d.verified);setIsAdmin(d.role==='ADMIN')}).catch((e)=>{if(e instanceof Error&&/登录已失效|请先登录|401/.test(e.message))logout()})},[token]); useEffect(()=>{const h=()=>{logout();setViewUser(null);setViewProfile(false);setNotice('登录已失效，请重新登录');setTimeout(()=>setNotice(''),3500);setModal('login')};window.addEventListener('tb-auth-expired',h);return()=>window.removeEventListener('tb-auth-expired',h)},[]); useEffect(()=>{if(!token)return;try{const p=JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));const exp=(p.exp||0)*1000;const ms=exp-Date.now();if(ms<=0)return;const refreshIn=Math.max(Math.min(ms-5*60*1000,ms/2),30000);const t=window.setTimeout(()=>{api<{token:string;username:string}>('/api/auth/refresh',{method:'POST'},token).then(r=>{setToken(r.token);localStorage.setItem('tb-token',r.token)}).catch(e=>console.warn('API:',e))},refreshIn);return()=>clearTimeout(t)}catch{return}},[token]);
 useEffect(()=>{if(!token)return;api<Notification[]>('/api/notifications',{},token).then(setNotifications).catch(e=>console.warn('API:',e));api<{count:number}>('/api/notifications/unread-count',{},token).then(d=>setUnreadCount(d.count)).catch(e=>console.warn('API:',e))},[token]);
 useEffect(()=>{if(!token)return;let ws:WebSocket|null=null;let timer:number|undefined;let closed=false;let retryCount=0;const connect=()=>{try{ws=new WebSocket('ws://localhost:8080/ws/notifications?token='+token);ws.onopen=()=>{retryCount=0};ws.onmessage=e=>{try{const d=JSON.parse(e.data);if(Array.isArray(d)){setNotifications(list=>[...d,...list].slice(0,50));setUnreadCount(c=>c+d.filter((x:Notification)=>!x.read).length)}else if(d&&typeof d.id==='number'){setNotifications(list=>[d as Notification,...list].slice(0,50));setUnreadCount(c=>c+1)}}catch{}};ws.onclose=()=>{if(!closed){const d=Math.min(3000*Math.pow(2,retryCount),30000);retryCount++;timer=window.setTimeout(connect,d)}};ws.onerror=()=>{ws?.close()}}catch{if(!closed){const d=Math.min(3000*Math.pow(2,retryCount),30000);retryCount++;timer=window.setTimeout(connect,d)}}};connect();return()=>{closed=true;if(timer)clearTimeout(timer);ws?.close()}},[token]);
 function showError(e:unknown){setNotice(e instanceof Error?e.message:'发生未知错误');setTimeout(()=>setNotice(''),3500)}
 async function submitAuth(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const registering=modal==='register';try{const r=await api<{token:string;username:string}>(`/api/auth/${registering?'register':'login'}`,{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password')})});setToken(r.token);setUser(r.username);localStorage.setItem('tb-token',r.token);localStorage.setItem('tb-user',r.username);setModal(null);setNotice(registering?`注册成功，欢迎加入 ${r.username}`:`欢迎回来，${r.username}`)}catch(err){showError(err)}}
 async function submitPost(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!active)return;try{await api(`/api/forums/${active.slug}/posts`,{method:'POST',body:JSON.stringify({title:postForm.title,content:postForm.content})},token);setModal(null);setPostForm({title:'',content:''});loadPosts();setNotice('帖子已发布');setTimeout(()=>setNotice(''),3500)}catch(err){showError(err)}}
