 function openProfile(){setMenu(false);setProfileTab('info');api<UserProfile>(`/api/users/${encodeURIComponent(user)}`,{},token).then(d=>{setProfileForm({id:d.id,username:d.username,verified:d.verified,avatarUrl:d.avatarUrl||'',bio:d.bio||'',signature:d.signature||'',following:d.following,followers:d.followers,isFollowing:d.isFollowing,isSelf:d.isSelf,mutual:d.mutual});setViewProfile(true)}).catch(showError)}
 function openUser(username:string){setViewPost(null);setViewUser(null);setUserTab('posts');setUserPosts([]);setUserFollowList([]);api<UserProfile>(`/api/users/${encodeURIComponent(username)}`,{},token).then(d=>{setViewUser(d);api<Page<Post>>(`/api/users/${encodeURIComponent(username)}/posts?size=20`,{},token).then(r=>setUserPosts(r.content)).catch(()=>setUserPosts([]))}).catch(showError)}
