 function loadProfileTab(tab:'info'|'posts'|'favorites'|'following'|'followers'){setProfileTab(tab);if(tab==='posts'){api<Page<Post>>(`/api/users/${encodeURIComponent(user)}/posts?size=20`,{},token).then(r=>setProfilePosts(r.content)).catch(()=>setProfilePosts([]))}else if(tab==='favorites'){api<Page<Post>>('/api/users/me/favorites?size=20',{},token).then(r=>setProfileFavPosts(r.content)).catch(()=>setProfileFavPosts([]))}else if(tab==='following'){api<UserView[]>(`/api/users/${encodeURIComponent(user)}/following`,{},token).then(setProfileFollowList).catch(()=>setProfileFollowList([]))}else if(tab==='followers'){api<UserView[]>(`/api/users/${encodeURIComponent(user)}/followers`,{},token).then(setProfileFollowList).catch(()=>setProfileFollowList([]))}}
