 async function handleAvatarChange(e:React.ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){showError(new Error('图片不能超过 2MB'));return}try{const fd=new FormData();fd.append('file',file);const res=await fetch('/api/upload',{method:'POST',headers:{Authorization:`Bearer ${token}`},body:fd});if(!res.ok)throw new Error((await res.json().catch(()=>({message:'上传失败'}))).message||'上传失败');const data=await res.json();setProfileForm(f=>({...f,avatarUrl:data.url}))}catch(err){showError(err)}}
 async function submitProfile(e:FormEvent<HTMLFormElement>){e.preventDefault();try{const r=await api<{token:string|null;user:UserProfile}>('/api/auth/me',{method:'PATCH',body:JSON.stringify({username:profileForm.username,avatarUrl:profileForm.avatarUrl,bio:profileForm.bio,signature:profileForm.signature})},token);if(r.token){setToken(r.token);localStorage.setItem('tb-token',r.token)}setUser(r.user.username);localStorage.setItem('tb-user',r.user.username);setVerified(r.user.verified);setViewProfile(false);setNotice('个人资料已更新');setTimeout(()=>setNotice(''),3500)}catch(err){showError(err)}}
