 const openPost=(p:Post)=>{setViewPost(p);setComments([]);setReplyTo(null);setEditPost(false);api<Post>(`/api/posts/${p.id}`).then(d=>setViewPost(d)).catch(showError);api<Comment[]>(`/api/posts/${p.id}/comments`).then(setComments).catch(showError)};
