 async function submitComment(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!viewPost)return;if(!token){setModal('login');return}const content=commentContent;if(!content.trim())return;const body:any={content};if(replyTo!=null)body.parentId=replyTo;try{await api(`/api/posts/${viewPost.id}/comments`,{method:'POST',body:JSON.stringify(body)},token);setReplyTo(null);setCommentContent('');api<Comment[]>(`/api/posts/${viewPost.id}/comments`).then(setComments).catch(showError);setViewPost({...viewPost,comments:viewPost.comments+1});setNotice('评论已发表');setTimeout(()=>setNotice(''),3500)}catch(err){showError(err)}}
 const notifIcon=(k:string)=>k==='REPLY'?'↩':k==='UPVOTE'?'↑':k==='MENTION'?'@':k==='FEATURED'?'★':k==='FOLLOW'?'✚':'•';
 async function handleNotifClick(n:Notification){if(!n.read){try{await api(`/api/notifications/${n.id}/read`,{method:'PATCH'},token);setNotifications(list=>list.map(x=>x.id===n.id?{...x,read:true}:x));setUnreadCount(c=>Math.max(0,c-1))}catch(err){showError(err)}}if(n.postId){setShowNotif(false);api<Post>(`/api/posts/${n.postId}`).then(d=>openPost(d)).catch(showError)}else setShowNotif(false)}
