 async function toggleLock(p:Post){if(!token){setModal('login');return}try{const updated=await api<Post>(`/api/posts/${p.id}/locked?value=${!p.locked}`,{method:'PATCH'},token);if(viewPost&&viewPost.id===p.id)setViewPost(updated);setPosts(list=>list.map(x=>x.id===p.id?updated:x));setNotice(updated.locked?'帖子已锁定':'帖子已解锁');setTimeout(()=>setNotice(''),3500)}catch(err){showError(err)}}
